from pathlib import Path
import sys,json,subprocess,runpy,copy
root=Path(sys.argv[1]);runpy.run_path(str(Path(__file__).with_name('certificate_pair_fixture.py')),run_name='__main__');store=root/'w';ledger=store/'observations.jsonl';public=store/'witness.pub';before=ledger.read_bytes()
def cli(*args):return subprocess.run([sys.executable,'-m','wireledger',*map(str,args)],capture_output=True,text=True)
base=['certificate-batch',ledger,'--public-key',public,'--sequence','3','--sequence','1'];r=cli(*base);assert r.returncode==0,r.stderr;data=json.loads(r.stdout);assert data['selected_sequences']==[3,1]and[r['sequence']for r in data['samples']]==[3,1]and data['samples'][0]['metadata']['spki_sha256']!=data['samples'][1]['metadata']['spki_sha256'];h=cli(*base,'--html');assert h.returncode==0;assert'BEGIN CERTIFICATE'not in h.stdout and'PRIVATE KEY'not in h.stdout;(root/'batch.html').write_text(h.stdout);(root/'expected.json').write_text(json.dumps(data));assert ledger.read_bytes()==before
for extra in[['--sequence','1'],['--sequence','0'],['--sequence','4'],['--index','99']]:
 r=cli(*base,*extra);assert r.returncode==1 and not r.stdout;assert ledger.read_bytes()==before
from wireledger.ledger import append,load_private
observation=copy.deepcopy(json.loads(before.splitlines()[0])['body']['observation']);field=next(k for k,v in observation['evidence'].items()if isinstance(v,list));observation['evidence'][field].append('bm90LWRlcg==');append(ledger,load_private(store/'witness.key'),observation);r=cli(*base,'--sequence','4');assert r.returncode==1 and not r.stdout;ledger.write_bytes(before.replace(b'localhost',b'tampered'));r=cli(*base);assert r.returncode==1 and not r.stdout;ledger.write_bytes(before)
code="from unittest.mock import patch;from wireledger.__main__ import main\nwith patch('socket.getaddrinfo',side_effect=RuntimeError('DNS forbidden')),patch('wireledger.__main__.load_private',side_effect=RuntimeError('key forbidden')):raise SystemExit(main("+repr(list(map(str,base)))+"))";assert subprocess.run([sys.executable,'-c',code],capture_output=True).returncode==0
